examples.code:
@inject MyNotionDataProvider DataProvider
@inject MyNotionAggregateProvider AggregateProvider
@inject MyTokenProvider TokenProvider

<TmNotionEditor DataProvider="@DataProvider"
                AggregateProvider="@AggregateProvider"
                TokenProvider="@TokenProvider"
                InitialPageId="my-page-id"
                Class="h-full" />

@using Tempo.Blazor.NotionEditor.Enums

@code {
    private static readonly IReadOnlySet<BlockType> AllowedTypes = new HashSet<BlockType>
    {
        BlockType.Paragraph,
        BlockType.Heading1,
        BlockType.Heading2,
        BlockType.BulletList,
        BlockType.NumberedList,
        BlockType.TodoItem,
    };
}

<TmNotionEditor DataProvider="@DataProvider"
                AggregateProvider="@AggregateProvider"
                AllowedBlockTypes="@AllowedTypes"
                InitialPageId="@_pageId" />

@using Tempo.Blazor.NotionEditor.Enums

@code {
    // Rich-text description blocks only — multi-page blocks are removed automatically in SinglePageMode.
    private static readonly IReadOnlySet<BlockType> DescriptionBlocks = new HashSet<BlockType>
    {
        BlockType.Paragraph, BlockType.Heading1, BlockType.Heading2, BlockType.Heading3,
        BlockType.BulletList, BlockType.NumberedList, BlockType.TodoItem,
        BlockType.Quote, BlockType.Callout, BlockType.Code, BlockType.Divider, BlockType.Image, BlockType.Table
    };

    void OpenElsewhere(string pageId) { /* host opens the linked page in a dialog / new tab */ }
}

<TmNotionEditor DataProvider="@DataProvider"
                AggregateProvider="@AggregateProvider"
                SinglePageMode="true"
                InitialPageId="@WorkItem.DescriptionPageId"
                AllowedBlockTypes="@DescriptionBlocks"
                OnPageNavigationRequested="OpenElsewhere" />
